# 취약점(Vulnerability) 예시: Python 3에서 실행 가능한 코드
checks = {"input_validated": False, "patched": True}
print([k for k, ok in checks.items() if not ok])

# XXE(XML 외부 엔티티) 예시: Python 3에서 실행 가능한 코드
parser_config = {"external_entities": False}
print("safe" if not parser_config["external_entities"] else "risky")

# 구성 오류 예시: Python 3에서 실행 가능한 코드
config = {"debug": False, "default_password": False}
print(all(config.values()) if False else not config["debug"] and not config["default_password"])

# 공급망 공격 예시: Python 3에서 실행 가능한 코드
dependencies = {"safe-lib": "verified", "new-lib": "unknown"}
print([k for k, v in dependencies.items() if v != "verified"])

# 의존성 취약점 예시: Python 3에서 실행 가능한 코드
deps = {"libA": "1.0", "libB": "2.3"}
vulnerable = {"libA"}
print([d for d in deps if d in vulnerable])

# 컨테이너 보안 예시: Python 3에서 실행 가능한 코드
image = {"runs_as_root": False, "secrets_inside": False}
print(not image["runs_as_root"] and not image["secrets_inside"])

# 네트워크 분리 예시: Python 3에서 실행 가능한 코드
allowed = {("web", "api"), ("api", "db")}
print(("web", "db") in allowed)

# 마이크로 세그멘테이션 예시: Python 3에서 실행 가능한 코드
policy = {("serviceA", "serviceB"): True, ("serviceA", "db"): False}
print(policy[("serviceA", "db")])

# MITRE ATT&CK 예시: Python 3에서 실행 가능한 코드
technique = {"id": "T1059", "name": "Command and Scripting Interpreter"}
print(technique["id"])

# 소셜 엔지니어링 예시: Python 3에서 실행 가능한 코드
request = {"urgent": True, "verified": False}
print("deny" if request["urgent"] and not request["verified"] else "allow")

# 암호화 키 관리 예시: Python 3에서 실행 가능한 코드
keys = {"active": "k2", "old": "k1"}
print(keys["active"])

# HSM(하드웨어 보안 모듈) 예시: Python 3에서 실행 가능한 코드
hsm = {"key_exportable": False, "can_sign": True}
print(hsm["can_sign"] and not hsm["key_exportable"])

# 키 에스크로 예시: Python 3에서 실행 가능한 코드
escrow = {"stored": True, "approvals_required": 2}
print(escrow["stored"] and escrow["approvals_required"] >= 2)

# 코드 서명 예시: Python 3에서 실행 가능한 코드
package = {"signed_by": "trusted", "hash_ok": True}
print(package["signed_by"] == "trusted" and package["hash_ok"])

# 샌드박스 예시: Python 3에서 실행 가능한 코드
permissions = {"read_tmp": True, "read_home": False}
print(permissions["read_tmp"] and not permissions["read_home"])

# 격리 실행 예시: Python 3에서 실행 가능한 코드
tasks = {"trusted": "main", "untrusted": "isolated"}
print(tasks["untrusted"])

# 컨테이너 탈출 예시: Python 3에서 실행 가능한 코드
container = {"privileged": False, "host_mount": False}
print("lower risk" if not container["privileged"] and not container["host_mount"] else "risky")

# 권한 상승(Linux) 예시: Python 3에서 실행 가능한 코드
user = {"sudo": False, "uid": 1000}
print("root" if user["uid"] == 0 else "limited")

# Capabilities 예시: Python 3에서 실행 가능한 코드
caps = {"CAP_NET_BIND_SERVICE"}
print("CAP_SYS_ADMIN" in caps)

# SELinux 예시: Python 3에서 실행 가능한 코드
context = {"process": "web_t", "file": "httpd_sys_content_t"}
print(context["process"].startswith("web"))

# 보안 기준선(Hardening) 예시: Python 3에서 실행 가능한 코드
baseline = {"ssh_root_login": False, "firewall": True, "patched": True}
print(all(baseline.values()) if False else baseline["firewall"] and baseline["patched"] and not baseline["ssh_root_login"])

# 사이드 채널 공격 예시: Python 3에서 실행 가능한 코드
observations = {"time_ms": 12, "power": 3.4}
print(observations.keys())

# 내부자 위협(Insider Threat) 예시: Python 3에서 실행 가능한 코드
access = {"user": "staff1", "downloads": 500}
print("review" if access["downloads"] > 100 else "ok")

# 취약점 공개 정책(Responsible Disclosure) 예시: Python 3에서 실행 가능한 코드
policy = {"contact": "security@example.com", "embargo_days": 90}
print(policy["contact"], policy["embargo_days"])
